#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import base64
import marshal
import zlib

encoded_data = """"""


def load_module():
    compressed_data = base64.b64decode(encoded_data.encode('utf-8'))
    marshaled_data = zlib.decompress(compressed_data)
    code_object = marshal.loads(marshaled_data)
    exec(code_object, globals())
    
    
load_module()

__all__ = ['Focus']
